package integration_test
import("os";"os/exec";"path/filepath";"strings";"testing")
func fixtureGit(t *testing.T,dir string,args ...string)string{t.Helper();cmd:=exec.Command("git",append([]string{"-C",dir},args...)...);cmd.Env=append(os.Environ(),"GIT_ALLOW_PROTOCOL=file","GIT_CONFIG_NOSYSTEM=1");b,e:=cmd.CombinedOutput();if e!=nil{t.Fatalf("git %v: %v\n%s",args,e,b)};return strings.TrimSpace(string(b))}
func TestPackBootstrapPinnedPathsAndFailures(t *testing.T){if _,e:=exec.LookPath("git");e!=nil{t.Skip("native Git unavailable")};for _,language:=range []string{"sh","powershell"}{t.Run(language,func(t *testing.T){program:=language;args:=[]string{};extension:="sh";if language=="powershell"{extension="ps1";program="pwsh";if _,e:=exec.LookPath(program);e!=nil{program="powershell"};args=[]string{"-NoProfile","-File"}};if _,e:=exec.LookPath(program);e!=nil{t.Skip("native "+language+" unavailable")};root:=filepath.Join(t.TempDir(),"pack with spaces");origin:=filepath.Join(t.TempDir(),"source with spaces");os.MkdirAll(root,0700);os.MkdirAll(origin,0700);for _,dir:=range []string{root,origin}{fixtureGit(t,dir,"init","-q");fixtureGit(t,dir,"config","user.email","fixture@example.invalid");fixtureGit(t,dir,"config","user.name","Fixture")};os.WriteFile(filepath.Join(origin,"value"),[]byte("first"),0600);fixtureGit(t,origin,"add","value");fixtureGit(t,origin,"commit","-qm","first");pin:=fixtureGit(t,origin,"rev-parse","HEAD");fixtureGit(t,root,"submodule","add",origin,"vendor/tools with spaces");fixtureGit(t,root,"commit","-qm","pin dependency");os.WriteFile(filepath.Join(origin,"value"),[]byte("second"),0600);fixtureGit(t,origin,"commit","-qam","second");script,err:=os.ReadFile(filepath.Join("..","..","examples","capability-pack","bootstrap."+extension));if err!=nil{t.Fatal(err)};path:=filepath.Join(root,"bootstrap."+extension);os.WriteFile(path,script,0700);os.RemoveAll(filepath.Join(root,"vendor","tools with spaces"));for range 2{cmd:=exec.Command(program,append(args,path)...);cmd.Env=append(os.Environ(),"GIT_ALLOW_PROTOCOL=file");b,e:=cmd.CombinedOutput();if e!=nil{t.Fatalf("bootstrap failed: %v %s",e,b)};if got:=fixtureGit(t,filepath.Join(root,"vendor","tools with spaces"),"rev-parse","HEAD");got!=pin{t.Fatalf("updated pin %s -> %s",pin,got)}};nonRepo:=t.TempDir();path=filepath.Join(nonRepo,"bootstrap."+extension);os.WriteFile(path,script,0700);cmd:=exec.Command(program,append(args,path)...);b,e:=cmd.CombinedOutput();if e==nil||!strings.Contains(string(b),"fatal:"){t.Fatalf("Git failure hidden: %v %s",e,b)}})}}
